const menu = JSON.parse($('Extrai Campos').item.json.menu_json || '[]');
const query = $input.query.toLowerCase();

const results = menu.filter(p => 
  p.name.toLowerCase().includes(query) || 
  (p.description && p.description.toLowerCase().includes(query)) ||
  (p.category && p.category.toLowerCase().includes(query))
);

if (results.length === 0) {
  return { found: false, message: 'Nenhum produto encontrado para: ' + query };
}

const formatted = results.slice(0, 5).map(p => 
  `• ${p.name} - R$ ${p.price.toFixed(2)}${p.description ? ' (' + p.description.substring(0, 50) + ')' : ''}`
).join('\n');

return {
  found: true,
  count: results.length,
  products: results.slice(0, 5),
  formatted: formatted
};

