const supabaseUrl = $env.SUPABASE_URL;
const supabaseKey = $env.SUPABASE_ANON_KEY;

const response = await fetch(supabaseUrl + '/functions/v1/geocode-and-calculate-delivery', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Authorization': 'Bearer ' + supabaseKey
  },
  body: JSON.stringify({
    establishment_id: $('Extrai Campos').item.json.establishment_id,
    address: $input.address,
    neighborhood: $input.neighborhood,
    cep: $input.cep
  })
});

const result = await response.json();

if (!result.success) {
  return {
    success: false,
    delivers: false,
    message: result.error || '❌ Não foi possível calcular a entrega'
  };
}

if (!result.delivers) {
  return {
    success: true,
    delivers: false,
    message: '❌ Infelizmente não entregamos nessa região.'
  };
}

return {
  success: true,
  delivers: true,
  fee: result.fee,
  distance_km: result.distance_km,
  estimated_time: result.estimated_time,
  message: `🛵 *ENTREGA DISPONÍVEL!*\n\n📍 Distância: ${result.distance_km} km\n💰 Taxa: R$ ${result.fee.toFixed(2)}\n⏱️ Tempo estimado: ${result.estimated_time} min`
};

const output = $input.item.json.output || '';
const maxLength = 400;

if (output.length <= maxLength) {
  return [{ json: { chunk: output, index: 0, total: 1, isLast: true } }];
}

const paragraphs = output.split('\n\n');
const chunks = [];
let currentChunk = '';

for (const para of paragraphs) {
  if ((currentChunk + '\n\n' + para).length <= maxLength) {
    currentChunk = currentChunk ? currentChunk + '\n\n' + para : para;
  } else {
    if (currentChunk) chunks.push(currentChunk);

    if (para.length <= maxLength) {
      currentChunk = para;
    } else {
      const sentences = para.match(/[^.!?]+[.!?]+/g) || [para];
      for (const sentence of sentences) {
        if ((currentChunk + ' ' + sentence).length <= maxLength) {
          currentChunk = currentChunk ? currentChunk + ' ' + sentence : sentence;
        } else {
          if (currentChunk) chunks.push(currentChunk);
          currentChunk = sentence.substring(0, maxLength);
        }
      }
    }
  }
}

if (currentChunk) chunks.push(currentChunk);

return chunks.map((chunk, i) => ({
  json: {
    chunk: chunk,
    index: i,
    total: chunks.length,
    isLast: i === chunks.length - 1
  }
}));
